#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$env:NODE_PATH="$basedir/..;$basedir/../../../node_modules"
$exe=""
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  $exe=".exe"
}
$ret=0
if (Test-Path "$basedir/node$exe") {
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe" "$basedir/../../../untun@0.2.2/node_modules/untun/dist/cli.mjs" $args
  } else {
    & "$basedir/node$exe" "$basedir/../../../untun@0.2.2/node_modules/untun/dist/cli.mjs" $args
  }
  $ret=$LASTEXITCODE
} else {
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe" "$basedir/../../../untun@0.2.2/node_modules/untun/dist/cli.mjs" $args
  } else {
    & "node$exe" "$basedir/../../../untun@0.2.2/node_modules/untun/dist/cli.mjs" $args
  }
  $ret=$LASTEXITCODE
}
exit $ret
